import numpy as np, json, os, re
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def tiles(I):
    H,W=I.shape; blk=min(H,W)
    if W>=H: return [np.array(I[:,c:c+blk]) for c in range(0,W,blk)]
    else: return [np.array(I[r:r+blk,:]) for r in range(0,H,blk)]
for n in range(1,5):
    I=np.array(G[f'Demo pair {n} input']); O=np.array(G['Demo pair '+str(n)+' output'])
    tt=tiles(I); ti=[i for i,t in enumerate(tt) if np.array_equal(t,O)][0]
    gc=Counter(I.ravel().tolist())
    feats=[]
    for i,t in enumerate(tt):
        cc=Counter(t.ravel().tolist())
        f={
            'freqsum':sum(gc[v]*cc[v] for v in cc),
            'ncommon':sum(cc[v]>0 for v in gc) , 
            'share_with_others':sum(1 for j in range(len(tt)) if j!=i and set(np.asarray(tt[j]).ravel()).intersection(set(np.asarray(t).ravel())))
        }
        feats.append(f)
    print('demo',n,'target',ti,feats)

